import{z as S,x as d,o as r,c as p,q as i,j as E,D as t,d as e,s as o,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"RSS 与多队列网卡","description":"","frontmatter":{"title":"RSS 与多队列网卡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rss-multiqueue.md","filePath":"cs/rss-multiqueue.md","lastUpdated":1791063341000}'),A={name:"cs/rss-multiqueue.md"};function B(c,a,u,h,m,P){const l=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="rss-与多队列网卡" tabindex="-1">RSS 与多队列网卡 <a class="header-anchor" href="#rss-与多队列网卡" aria-label="Permalink to &quot;RSS 与多队列网卡&quot;">​</a></h1><div class="epigraph"><p>RSS 用包头哈希选择接收队列，每队列绑不同 CPU 的 NAPI，使多流并行而不在单核 livelock。</p><footer>—— 据 Microsoft RSS 白皮书直觉；Linux 对 indirection table 与 XPS 的文档</footer></div><p><a href="/cs/napi">NAPI</a> 每队列一份。<a href="/cs/dpdk-kernel-bypass">DPDK</a> 也按队列绑核。缺口是 <strong>RSS</strong>：硬件把流散开，以及 XPS 在发送侧对称。不是存储 mq 的复制粘贴——哈希对象是五元组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单队列：万兆一根 NAPI 打满一核。RSS：NIC 算 hash，查间接表得队列号，MSI-X 到对应 CPU。缺口：哈希不对称则转发方向换核，缓存冷；对称 RSS 或 Toeplitz 密钥配置；RPS 是无 RSS 硬件时的软件 steer。本课不把每一家 ethtool 字段当作业。<span class="marginnote">术语翻译：间接表（indirection table）就是用「存一张几百项的『哈希值低几位 → 队列号』小表」的手段来做「不改网卡芯片逻辑、只改表项就能调流量分布」的事——想把某个队列的份量挪走，改表就行，不用换哈希函数。</span></p><p><span class="marginnote">Flow Director / aRFS 可把已有套接字所在核告诉网卡。XPS：发送队列按 CPU 选，减少跨核锁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化：建 N 对 RX/TX 队列，设间接表。运行：同五元组进同队列，TCP 同流有序。对照 <a href="/cs/blk-schedulers">blk-mq</a>：blk-mq 按提交者 CPU；RSS 按包头，与提交者无关。对照 netns：每设备自己的队列，veth 软件哈希另说。<span class="marginnote">数字实例：一块 8 队列网卡、间接表 128 项时，每个队列平均分到 16 个表项；若把其中 16 项全改成队 0，队 0 的流量就翻倍——用表项的比例做负载整形，是最粗糙也最常用的旋钮。</span></p>',8)),(r(),E(n,null,{default:t(()=>[o(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20HASH%5B%22RSS%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20LUT%5B%22%E9%97%B4%E6%8E%A5%E8%A1%A8%22%5D%0A%20%20LUT%20--%3E%20Q%5B%22RX%20%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20CPU%5B%22%E5%AF%B9%E5%BA%94%20CPU%20%E7%9A%84%20NAPI%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("RSS 把并行从「更多中断」变成「更多队列」，是多核网络的默认几何。它不保证应用线程在同一核——还要 RFS 或用户绑核。不要写成量化分片。与 "),s("a",{href:"/cs/gro-gso"},"GRO"),e("：GRO 在单队列内合并，跨队列不能拼同一流（同流本应同队列）。"),s("span",{class:"marginnote"},"常见误区：初学者容易以为「RSS 分好了核，应用线程自然也在那个核上」——RSS 只保证同一流的中断与软中断落在同一 CPU；应用线程若被调度到别的核，每个包还要跨核递交一次，得靠 RFS 或用户态绑核把这两层对齐。")],-1)),(r(),E(n,null,{default:t(()=>[o(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%90%91%E5%8C%85%20%E4%BA%94%E5%85%83%E7%BB%84%20A%E5%88%B0B%22%5D%20--%3E%20H1%5B%22RSS%20%E5%93%88%E5%B8%8C%20%E6%AD%A3%E5%90%91%E7%AE%97%22%5D%0A%20%20H1%20--%3E%20Q1%5B%22%E8%90%BD%E5%88%B0%E9%98%9F%E5%88%97%20q3%20CPU3%22%5D%0A%20%20OUT%5B%22%E5%9B%9E%E5%90%91%E5%8C%85%20%E4%BA%94%E5%85%83%E7%BB%84%20B%E5%88%B0A%22%5D%20--%3E%20H2%5B%22RSS%20%E5%93%88%E5%B8%8C%20%E5%8F%8D%E5%90%91%E7%AE%97%22%5D%0A%20%20H2%20--%3E%20Q2%5B%22%E5%93%88%E5%B8%8C%E4%B8%8D%E5%AF%B9%E7%A7%B0%E6%97%B6%20%E6%8D%A2%E5%88%B0%20q1%20CPU1%22%5D%0A%20%20FIX%5B%22%E6%94%B9%E7%94%A8%E5%AF%B9%E7%A7%B0%E5%93%88%E5%B8%8C%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20SAME%5B%22%E5%8F%8C%E5%90%91%E5%90%8C%E9%98%9F%E5%88%97%20%E5%90%8C%E4%B8%80%E6%A0%B8%20%E7%BC%93%E5%AD%98%E7%83%AD%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>重配置队列数会扰动亲和，生产上要谨慎。</p><p>实现上：间接表可把部分队列置零以离线 CPU。对称哈希让转发五元组双向同队列。隧道封装后若只哈希外层，内层流会撞同一队列。 读法上只引用<a href="/cs/dpdk-kernel-bypass">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>RSS 与多队列网卡</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 infiniband 的 RQ 与 CQ 命名（RDMA 后课）。不保证隧道封装后内层哈希（RSS 可能只看外层）。下一课把拷贝再削：零拷贝网络。</p><p>版本字段会变，课序钉的是机制对象「RSS 与多队列网卡」，不是某一主线内核的结构体名。 后课默认：多队列靠 RSS 散列到 CPU。发送/接收少拷贝的机制，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSS 按流哈希选 RX 队列并绑 CPU。</li><li>XPS/RFS 补发送与应用核亲和。</li><li>零拷贝网络是下一课。</li><li>出处：RSS 文献；Linux networking；ethtool 队列。</li></ul>',9))])}const D=S(A,[["render",B]]);export{C as __pageData,D as default};
